SELECT FROM t_auth_user
WHERE username LIKE CONCAT('%', #{keyword}, '%') OR display_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE t_auth_user
SET last_login_at = NOW(3)
WHERE id = #{id}

UPDATE t_auth_user
SET last_login_at = NOW(3)
WHERE id = #{id}
  AND is_active = 1
  AND auth_provider = 'LOCAL'
  AND auth_version = #{expectedAuthVersion}

UPDATE t_auth_user
SET auth_version = auth_version + 1
WHERE id = #{id}
